changeSet.sql:
alter table dokumentart drop constraint dokumentart_aufbewahrung_ab_ck;
alter table dokumentart add constraint dokumentart_aufbewahrung_ab_ck
    check (aufbewahrung_ab in ('GESCHAEFTSJAHR', 'GUELTIG_BIS', 'BELEGDATUM', 'FELD'));
alter table dokumentart add constraint dokumentart_aufbewahrung_feld_ck
    check ((coalesce(aufbewahrung_ab = 'FELD', false)) = (aufbewahrung_feld is not null)
        and (aufbewahrung_feld is null or aufbewahrung_feld ~ '^[a-z][a-z0-9_]{0,62}$'));
